class Solution {
public:
    struct TrieNode {
        TrieNode* child[26] = {nullptr};
    };
    int countDistinct(string s) {
        TrieNode* root = new TrieNode();
        int ans = 0;
        int n = s.size();
        for (int i = 0; i < n; i++) {
            TrieNode* curr = root;
            for (int j = i; j < n; j++) {
                int idx = s[j] - 'a';
                if (!curr->child[idx]) {
                    curr->child[idx] = new TrieNode();
                    ans++;
                }
                curr = curr->child[idx];
            }
        }
        return ans;
    }
};

class Solution {
    static class TrieNode {
        TrieNode[] child = new TrieNode[26];
    }
    public int countDistinct(String s) {
        TrieNode root = new TrieNode();
        int ans = 0;
        int n = s.length();
        for (int i = 0; i < n; i++) {
            TrieNode curr = root;
            for (int j = i; j < n; j++) {
                int idx = s.charAt(j) - 'a';
                if (curr.child[idx] == null) {
                    curr.child[idx] = new TrieNode();
                    ans++;
                }
                curr = curr.child[idx];
            }
        }
        return ans;
    }
}

var countDistinct = function(s) {
    const root = {};
    let ans = 0;
    const n = s.length;
    for (let i = 0; i < n; i++) {
        let curr = root;
        for (let j = i; j < n; j++) {
            const ch = s[j];
            if (!curr[ch]) {
                curr[ch] = {};
                ans++;
            }
            curr = curr[ch];
        }
    }
    return ans;
};
